import asyncio
import functools
from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient

app = FastAPI()

# Case 1: Regular function wrapped by an async wrapper
def regular_func():
    return "regular"

def async_wrapper(func):
    @functools.wraps(func)
    async def wrapper(*args, **kwargs):
        return await func(*args, **kwargs) if asyncio.iscoroutinefunction(func) else func(*args, **kwargs)
    return wrapper

wrapped_regular = async_wrapper(regular_func)

# Case 2: Async function wrapped by a regular wrapper
async def async_func():
    return "async"

def regular_wrapper(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

wrapped_async = regular_wrapper(async_func)

# Case 3: partial of an async function
partial_async = functools.partial(async_func)

# Case 4: partial of a wrapped async function
partial_wrapped_async = functools.partial(wrapped_async)

@app.get("/case1")
async def case1():
    return await wrapped_regular()

@app.get("/case2")
async def case2():
    # If FastAPI doesn't recognize wrapped_async as async, it might not await it if it was a dependency
