    return val

async def async_dep():
    return "async_dep"

def sync_wrapper(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

wrapped_async_dep = sync_wrapper(async_dep)

@app.get("/dep2")
async def dep2(val = Depends(wrapped_async_dep)):
    return val

